/**
 * File Description: Input/output corpus for Jev decision parsing and request construction. Both inputs are AUTHORED,
 * not captured: no real Jev response survives in the repo or in past run data, so the state and the reply follow the
 * shape of backend/jev.ts. The request payload and the parsed answer are generated by the real code and reviewed by diff.
 * Inputs and outputs: an authored Jev decision state and reply -> request payload and parsed Jev answer expectations.
 * Used by: npm test (found by glob), the CI unit job.
 */

import test from "node:test";
import { expectFile, formatForReview } from "./testSupport/expectFile";
import { buildDecisionRequest, parseDecisionResponse, DEFAULT_JEV_MODEL } from "./jev";

// AUTHORED sample (not captured): the decision state sent to Jev.
const state = {
  visual: "A command appears in a terminal window",
  narration: "Run npm install to add the dependency to your project.",
  onscreen: ["npm install @typesafe-ai/sdk"],
  activeComponents: ["TextReveal"],
  sceneTitle: "Installation",
};

// AUTHORED sample (not captured): a Jev reply in the response shape that parseDecisionResponse accepts.
const reply = {
  model: "typesafe/jev-1.13",
  answers: {
    primitive: {
      type: "choice",
      choice: "CodeBlock",
      confidence: 0.88,
      probabilities: { CodeBlock: 0.88, TextReveal: 0.12 },
    },
    servesPhrase: { type: "choice", choice: "phrase1" },
  },
  usage: { input_tokens: 120, output_tokens: 15 },
};

// Records Jev's generated request and the real parser's normalized answer for the authored inputs.
test("Jev decision parser matches the authored prompt and reply corpus", () => {
  const request = buildDecisionRequest(state, DEFAULT_JEV_MODEL);
  const parsed = parseDecisionResponse(reply, ["Run npm install to add the dependency to your project"]);
  expectFile(formatForReview({ request, reply, parsed }), "jev/decision.json");
});
